{
  "root": "main_stack",
  "state": {
    "ira_comparison_data": [
      {
        "feature": "Tax Deductibility (Contributions)",
        "roth_ira": "Contributions are made with after-tax dollars and are not tax-deductible.",
        "traditional_ira": "Contributions may be tax-deductible, reducing your current taxable income. For a single filer earning $70,000, contributions are generally fully deductible."
      },
      {
        "feature": "Tax on Growth & Qualified Withdrawals",
        "roth_ira": "Earnings grow tax-free. Qualified withdrawals in retirement (after age 59.5 and 5-year rule met) are tax-free.",
        "traditional_ira": "Earnings grow tax-deferred. Withdrawals in retirement are taxed as ordinary income."
      },
      {
        "feature": "Income Limits for Direct Contributions",
        "roth_ira": "For 2024, direct contributions begin to phase out for single filers with Modified Adjusted Gross Income (MAGI) between $146,000 and $161,000. A $70,000 earner can contribute directly.",
        "traditional_ira": "No income limit for contributions, but deductibility may phase out if you are covered by a retirement plan at work and your income exceeds certain thresholds."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "description",
        "ira_table_card",
        "note_text",
        "footer_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Roth vs. Traditional IRA Comparison",
        "variant": "h2"
      },
      "children": []
    },
    "description": {
      "type": "Text",
      "props": {
        "text": "Understand the key differences between Roth and Traditional Individual Retirement Accounts to make an informed decision for your retirement savings.",
        "variant": "body"
      },
      "children": []
    },
    "ira_table_card": {
      "type": "Card",
      "props": {},
      "children": [
        "ira_table_title",
        "ira_comparison_table"
      ]
    },
    "ira_table_title": {
      "type": "Text",
      "props": {
        "text": "IRA Comparison Details",
        "variant": "h3"
      },
      "children": []
    },
    "ira_comparison_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "feature",
            "label": "Feature"
          },
          {
            "key": "roth_ira",
            "label": "Roth IRA"
          },
          {
            "key": "traditional_ira",
            "label": "Traditional IRA"
          }
        ],
        "statePath": "/ira_comparison_data",
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "feature",
        "highlightColumns": [
          "roth_ira",
          "traditional_ira"
        ]
      },
      "children": []
    },
    "note_text": {
      "type": "Text",
      "props": {
        "text": "Note: Income limits and deductibility rules are subject to change annually. Consult a financial advisor for personalized advice.",
        "variant": "caption"
      },
      "children": []
    },
    "footer_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "justify": "center",
        "gap": "sm"
      },
      "children": [
        "footer_text_1",
        "footer_text_2"
      ]
    },
    "footer_text_1": {
      "type": "Text",
      "props": {
        "text": "Data as of 2024.",
        "variant": "caption"
      },
      "children": []
    },
    "footer_text_2": {
      "type": "Text",
      "props": {
        "text": "Source: IRS.gov",
        "variant": "caption"
      },
      "children": []
    }
  }
}
